// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadAnton = makeLoadFont('Anton');
const loadMontserrat = makeLoadFont('Montserrat');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: antonFamily } = loadAnton();
const { fontFamily: montserratFamily } = loadMontserrat();



export type JackpotPopupProps = Record<string, any>;

const JackpotPopup: React.FC<JackpotPopupProps> = ({
  backgroundColor = "#120a1f",
  transparentBackground = true,
  durationInSeconds = 8,
  titleText = "MAJOR JACKPOT",
  jackpotAmount = 4000,
  currencySymbol = "$",
  cardPrimaryColor = "#2a0a4a",
  cardSecondaryColor = "#110022",
  accentColor = "#FFD700",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Global Timing
  const cardEntryFrame = 5;
  const countStartFrame = 25;
  const particleStartFrame = 15;

  // Background Overlay Animation (dimming effect to focus on pop-up)
  const overlayOpacity = interpolate(frame, [0, 20], [0, 0.8], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Card Animation (Spring up and scale)
  const cardSpring = spring({
    fps,
    frame: frame - cardEntryFrame,
    config: { damping: 12, stiffness: 100, mass: 0.8 },
  });

  const cardScale = interpolate(cardSpring, [0, 1], [0.3, 1]);
  const cardY = interpolate(cardSpring, [0, 1], [height * 0.5, 0]);

  // Jackpot Count-Up Animation
  const countProgress = spring({
    fps,
    frame: frame - countStartFrame,
    config: { damping: 20, mass: 1.5, stiffness: 40 },
  });

  const currentJackpot = interpolate(
    countProgress,
    [0, 1],
    [0, jackpotAmount],
    {
      extrapolateRight: "clamp",
      extrapolateLeft: "clamp",
    }
  );

  const formattedAmount = `${currencySymbol}${new Intl.NumberFormat(
    "en-US"
  ).format(Math.floor(currentJackpot))}`;

  // Pulse effect for the amount text once it finishes counting
  const pulsePhase = countProgress >= 0.99 ? frame * 0.1 : 0;
  const pulseScale = countProgress >= 0.99 ? 1 + Math.sin(pulsePhase) * 0.03 : 1;

  // Title Text Animation
  const titleOpacity = interpolate(
    frame - (cardEntryFrame + 5),
    [0, 10],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );
  const titleY = interpolate(
    frame - (cardEntryFrame + 5),
    [0, 15],
    [20, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // Particles / Confetti
  const numParticles = 24;
  const particles = Array.from({ length: numParticles }).map((_, i) => {
    const angle = (i / numParticles) * Math.PI * 2;
    // Deterministic random for varied speeds and distances
    const randDist = random(`dist-${i}`);
    const randRot = random(`rot-${i}`);
    const randDelay = random(`delay-${i}`) * 10;
    
    const pSpring = spring({
      fps,
      frame: frame - (particleStartFrame + randDelay),
      config: { damping: 14, stiffness: 80 },
    });

    const maxDist = width * (0.3 + randDist * 0.3);
    const dist = interpolate(pSpring, [0, 1], [0, maxDist]);
    const x = Math.cos(angle) * dist;
    const y = Math.sin(angle) * dist + (frame - particleStartFrame) * 2; // Add gravity

    const pOpacity = interpolate(
      frame - (particleStartFrame + randDelay),
      [0, 10, fps * durationInSeconds - 30, fps * durationInSeconds - 10],
      [0, 1, 1, 0],
      { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
    );

    const pScale = interpolate(pSpring, [0, 1], [0, 0.5 + randDist * 1]);
    const pRotation = interpolate(frame, [0, 150], [0, 360 * (randRot > 0.5 ? 1 : -1)]);

    // Alternating between coins, stars, and sparkles
    const emojis = ["💰", "✨", "💵", "🎊"];
    const emoji = emojis[Math.floor(random(`emoji-${i}`) * emojis.length)];

    return { id: i, x, y, pOpacity, pScale, pRotation, emoji };
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        transition: "none",
        overflow: "hidden",
      }}
    >
      {/* Dark Overlay */}
      {!transparentBackground && (
        <AbsoluteFill
          style={{
            backgroundColor: "#000000",
            opacity: overlayOpacity,
            transition: "none",
          }}
        />
      )}

      {/* Particle Layer (Behind the card) */}
      <AbsoluteFill
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        {particles.map((p) => (
          <div
            key={p.id}
            style={{
              position: "absolute",
              fontSize: `${width * 0.05}px`,
              opacity: p.pOpacity,
              transform: `translate(${p.x}px, ${p.y}px) scale(${p.pScale}) rotate(${p.pRotation}deg)`,
              transition: "none",
            }}
          >
            {p.emoji}
          </div>
        ))}
      </AbsoluteFill>

      {/* Main Card Container */}
      <AbsoluteFill
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        <div
          style={{
            width: width * 0.55,
            padding: `${height * 0.08}px ${width * 0.04}px`,
            borderRadius: width * 0.03,
            background: `radial-gradient(circle at 50% 0%, ${cardPrimaryColor}, ${cardSecondaryColor})`,
            boxShadow: `0 0 ${width * 0.04}px ${accentColor}40, inset 0 0 ${width * 0.02}px ${accentColor}20`,
            border: `4px solid ${accentColor}`,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            transform: `translateY(${cardY}px) scale(${cardScale})`,
            transformOrigin: "center center",
            transition: "none",
            position: "relative",
            overflow: "hidden",
          }}
        >
          {/* Card Inner Glow/Highlight */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              right: 0,
              height: "40%",
              background: `linear-gradient(180deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0) 100%)`,
              pointerEvents: "none",
              transition: "none",
            }}
          />

          {/* Title Text */}
          <h2
            style={{
              fontFamily: montserratFamily,
              fontWeight: 900,
              fontSize: width * 0.04,
              color: "#FFFFFF",
              letterSpacing: width * 0.005,
              margin: 0,
              marginBottom: height * 0.02,
              opacity: titleOpacity,
              transform: `translateY(${titleY}px)`,
              textShadow: `0 ${height * 0.005}px ${height * 0.01}px rgba(0,0,0,0.5)`,
              textAlign: "center",
              transition: "none",
              zIndex: 2,
            }}
          >
            {titleText}
          </h2>

          {/* Jackpot Amount Background Glow */}
          <div
            style={{
              position: "absolute",
              width: width * 0.4,
              height: height * 0.3,
              background: `radial-gradient(circle, ${accentColor}60 0%, transparent 70%)`,
              filter: "blur(40px)",
              opacity: countProgress >= 0.99 ? 0.8 + Math.sin(pulsePhase) * 0.2 : countProgress,
              transition: "none",
              zIndex: 1,
            }}
          />

          {/* Jackpot Amount Text */}
          <h1
            style={{
              fontFamily: antonFamily,
              fontSize: width * 0.12,
              color: accentColor,
              margin: 0,
              lineHeight: 1.1,
              transform: `scale(${pulseScale})`,
              textShadow: `
                0 ${height * 0.01}px 0 #b38f00,
                0 ${height * 0.02}px ${height * 0.03}px rgba(0,0,0,0.8),
                0 0 ${width * 0.02}px ${accentColor}80
              `,
              textAlign: "center",
              transition: "none",
              zIndex: 2,
              // Background clip for metallic text effect
              backgroundImage: `linear-gradient(180deg, #FFFFFF 0%, ${accentColor} 50%, #b38f00 100%)`,
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
            }}
          >
            {formattedAmount}
          </h1>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default JackpotPopup;